/** Maintained product descriptions; coverage is checked against the public MCP contract. */
export const mcpCapabilities = [
  { id: 'game-studio', icon: 'layout-line', title: 'Build and test a local playable game', description: 'Create a draft (a portrait single-player draft can be a playable ad: first-frame play, short levels, an end card whose call-to-action may open App Store or Google Play), inspect and edit its files, validate deterministic rules, simulate routes, run headless playtests and capture a game-only cover. Update metadata and status, publish to the local market only when authorized, or record a silent gameplay trailer. Chrome, loopback permission and export runtimes must already be available; failures do not install them. Publication is local, and automated checks do not establish human gameplay acceptance.', tools: ['openmotion_game_create', 'openmotion_game_get', 'openmotion_game_read_file', 'openmotion_game_write_files', 'openmotion_game_update_meta', 'openmotion_game_capture_cover', 'openmotion_game_playtest', 'openmotion_game_simulate', 'openmotion_game_trailer', 'openmotion_game_validate', 'openmotion_game_set_status', 'openmotion_game_publish'], prompt: 'Read openmotion://workflow/game/start. Create my agreed game brief with openmotion_game_create, retain the returned id, inspect its card and files, and write only that game. Validate, simulate reference and idle routes, then run headless playtests and inspect their assertions. Capture a game-only cover and update title, controls and translations. Report unavailable Chrome, loopback or export components without installing them. Set ready only after checks; ask for local publication authorization before openmotion_game_publish. If I request a trailer, start openmotion_game_trailer and poll action=status, inspect the footage and verify final playback. Human gameplay acceptance remains separate.' },
  { id: 'timeline-hover', icon: 'play-fill', title: 'Inspect timeline frames', description: 'Pause playback, then hover over the ruler or clips to inspect a silent frame preview. Click the ruler to jump there. No model or export is needed. Moving away closes it; if loading fails, move away and try again.', tools: ['openmotion_open_preview'], prompt: 'Open the existing project with openmotion_open_preview so I can hover over the timeline to inspect frames, then click the ruler to jump. Preserve the source and selection; do not export or generate media.' },
  { id: 'fullscreen', icon: 'fullscreen-line', title: 'Fullscreen playback', description: 'Watch the video with the player fullscreen button or F; Esc returns to editing. Position and editor zoom are preserved. Embedded hosts may block browser fullscreen.', tools: ['openmotion_open_preview'], prompt: 'Open this project with openmotion_open_preview. I will enter fullscreen from the player. Preserve the project; do not render or edit it.' },
  { id: 'canvas-captions', icon: 'layout-2-line', title: 'Canvas and caption controls', description: "Change the current canvas from the timeline and use CC On / Off. No model is required. First enabling creates an empty caption track; adding captions fills it. Locked tracks must be unlocked. Conflicts require reloading the latest project. Framing uses letterbox or center crop, without automatic subject detection.", tools: ['openmotion_edit_project', 'openmotion_assets_use'], prompt: 'Read this project and its current revision/version. Use openmotion_edit_project with canvas={compositionPath:"index.html",ratio:"9:16",fit:"contain"} to change the canvas. Then reread the revision/version and enable captions with openmotion_assets_use(action=transcript, transcript.command=caption_toggle, visible=true, compositionPath="index.html"). Use a stable requestId for each operation. Preserve content, respect locked tracks and stop to reread after conflicts. Open the saved preview and verify the canvas and C1 track. This needs no model and creates no transcript or invented captions.' },
  { id: 'editing', icon: 'text', title: 'Edit text and captions', description: 'Add text or manual captions at the playhead without a model. Import music, trim or split clips, or generate captions directly from video and audio with configured ASR. For constant-speed source edits, update playback rate and duration together, preserving the source in-point and respecting linked members, locks and ripple placement.', tools: ['openmotion_assets_use', 'openmotion_import_assets', 'openmotion_edit_project'], prompt: 'Add an editable title and manual captions to this project using caption_add, preserving its existing clips. Read the current project revision first. Use explicitly supplied timing, and ask if timing or text is missing.' },
  { id: 'transcript', icon: 'clipboard-line', title: 'From speech to platform versions', description: 'Import audio or video, record locally, transcribe with your configured model, correct the transcript and add editable captions. Hand an Agent the source links, language choices and platform brief for independent versions.', tools: ['openmotion_assets_use', 'openmotion_manage_project', 'openmotion_edit_project', 'openmotion_export_request'], prompt: 'Help me turn my source media into reviewed transcripts, editable captions and platform versions. First identify my source project, inspect configured transcription models and ask which subtitle languages and platforms I need.' },
  { id: 'projects', icon: 'folder-open-line', title: 'Manage local projects', description: 'Rename, duplicate, locate, share, trash, restore and permanently delete projects from each project menu.', tools: ['openmotion_manage_project'], prompt: 'Duplicate this project as an independent editable copy.' },
  { id: 'sharing', icon: 'folder-open-line', title: 'Share editable projects', description: 'Share editable projects as ZIP files. Importing creates independent copies.', tools: ['openmotion_project_archive'], prompt: 'Export all my OpenMotion projects as a ZIP for offline sharing.' },
  { id: 'create', icon: 'clapperboard-line', title: 'From an idea to an editable film', description: 'Turn an idea or reference into motion graphics, product films and ads. Keep an editable project you can return to.', tools: ['openmotion_create_project', 'openmotion_edit_project'], prompt: 'Create a 15-second product film with three scenes, animated typography and an editable project. Ask me for the product and brand first.' },
  { id: 'templates', icon: 'layout-grid-line', title: 'Start with a template', description: 'Browse editable templates, brand references and creative guides. Ask your Agent to adapt a template or rebuild a reference for your brand.', tools: ['openmotion_list_templates', 'openmotion_get_template'], prompt: 'Show me OpenMotion templates for a product launch. Explain which are editable projects and which are references before creating anything. For an editable template, create an independent project; if opening fails, retry that exact project rather than making another copy. For a reference, read its guidance and ask for my content before authoring. Copying from the library does not send a message or create a film.' },
  { id: 'skills', icon: 'book-open-line', title: 'Find a video Skill by scenario', description: 'Search every OpenMotion video Skill, such as de-AI copy, growth teardowns or long-to-short cuts, without installing it first. Your Agent reads the Skill’s instructions and follows them to make an editable project. Skills already installed in your Agent keep working as before.', tools: ['openmotion_list_skills', 'openmotion_get_skill'], prompt: 'Recommend two or three OpenMotion Skills for turning a long talk into short clips. Use openmotion_list_skills, give each a one-line reason, and wait for my choice. Then read it with openmotion_get_skill and follow its SKILL.md; use only the supporting files it lists and verify downloads before running them. Ask for my source video before creating a project.' },
  { id: 'media', icon: 'sparkling-line', title: 'Generate images, video, music and voice', description: 'Choose a scene or filter its compatible models under Image, Video or Audio. In the generator or Studio, switch provider and model with the same prompt and references. Generate to save the result in Assets.', tools: ['openmotion_media_use'], prompt: 'Help me generate media with OpenMotion. First inspect my media providers and check account mediaEntitlement as well as availability. Continue model discovery for an available OpenDesign account with mediaEntitlement included or signed-in unknown, or another usable provider under my preferences and consent. Continue my original request or ask what media I want to generate or reference video I want to recreate. When setup is needed, use the settingsHandoff from inspect and follow the page handoff. If account mediaEntitlement is not-included and no other usable provider is available or I prefer the account route, use openmotion_open_preview with target=providers and entry=agent_media_upgrade_go for Go or entry=agent_media_upgrade_free for Free. Tell me Free and Go do not include multimodal generation and OpenDesign Plus or above is required. Guide me to click Upgrade to Plus directly on the opened OpenDesign page in Model providers. If there is no usable provider and sign-in is needed, use entry=agent_media_signed_out and guide me to click Sign in with OpenDesign directly on the opened OpenDesign page. For a rejected saved key, use entry=agent_media_key_rejected and guide me to replace it. Use entry=agent_media_handbook only if no specific reason applies. I can also save an OpenDesign Cloud / BYOK API key in Model providers. Keep keys in settings. Ask me to confirm after setup, then inspect again and resume my original request. Read the selected provider guide and model schema, explain the model and cost before generating, then track the original job.' },
  { id: 'library', icon: 'folder-open-line', title: 'Create and reuse assets', description: 'Upload or generate images, video and audio in Assets using model-supported references. Resume interrupted Cloud tasks or account image downloads without generating again; retry saving retained files separately. Read exact versions and import chosen assets into your films.', tools: ['openmotion_assets_use', 'openmotion_assets'], prompt: 'For an interrupted account image download, use openmotion_assets_use action=resume with its original jobId and a stable requestId; keep the original prompt and model and do not generate again. List my OpenMotion asset library. Help me generate a new asset or edit an existing version, keep the original, read the exact version to inspect its media, then import the chosen version into my project.' },
  { id: 'assets', icon: 'folder-open-line', title: 'Bring your own material', description: 'Import local images, video, audio and font files. Keep selected fonts and their licenses with the editable project.', tools: ['openmotion_import_assets'], prompt: 'Help me choose fonts for my project’s language and brand using the OpenMotion font catalog. Download only the selected faces, import them with their licenses, then check the actual text in the project.' },
  { id: 'preview', icon: 'play-fill', title: 'Edit together in the same Studio', description: 'Preview and refine your Agent’s work in Studio, or ask the Agent to keep editing the same project.', tools: ['openmotion_get_project', 'openmotion_open_preview'], prompt: 'Read my current OpenMotion project and open its latest editable preview. Keep the project identity and verify the visible result before continuing. For a new video generation round, use openmotion_open_preview action=begin before authoring. When the video artifact is ready, call action=complete_generation with workId, requestId, expectedRevision and expectedVersionId immediately, including background creation. Then continue to preview or export as requested.' },
  { id: 'history', icon: 'history-line', title: 'Keep every creative direction', description: 'Browse saved versions and restore an earlier direction as a new version. Keep the history while you refine the result.', tools: ['openmotion_list_versions', 'openmotion_restore_version'], prompt: 'List versions of my OpenMotion project and explain the differences. Wait for me to choose before restoring a version.' },
  { id: 'export', icon: 'download-2-line', title: 'Deliver a finished video', description: 'In Export, download the current video or an existing scene, download timeline captions as SRT/VTT, or prepare a platform version. Keep the editable project.', tools: ['openmotion_export_request', 'openmotion_export_cancel', 'openmotion_assets_use'], prompt: 'Read the selected project with openmotion_get_project. Export the agreed version with openmotion_export_request using versionId, expectedRevision, a stable requestId and the correct audio policy. Use compositionPath only when I select an existing scene; otherwise export the full video. Follow the same job and verify playback. For subtitles, call openmotion_assets_use with action=transcript and command=caption_export, projectId, compositionPath and format=srt or vtt. It exports saved visible timeline captions, including manual edits, without an ASR model. Use caption_tracks to choose one track via transcriptId when needed. If no visible captions exist, ask me to add or enable them; never fabricate speech. Return the files and editable project.' },
  { id: 'design-studio', icon: 'layout-line', title: 'Build HTML prototypes, decks and documents', description: 'Create responsive HTML prototypes, 16:9 slide decks, print-ready documents, website clones, live artifacts and WebGL experiences in Design Studio. Browse bundled templates, design systems and Skills, write revision-checked files with automatic vN versions, preview across Desktop, Tablet and Mobile, export PDF/PNG/PPTX/HTML/ZIP and round-trip with Open Design.', tools: ['openmotion_design_catalog', 'openmotion_design_project', 'openmotion_design_edit'], prompt: designBriefPrompt({ scenario: 'prototype', brief: 'Design a responsive SaaS landing page with clear hero, feature comparison and pricing.' }) },
  { id: 'design-annotations', icon: 'chat-1-line', title: 'Revise HTML designs from annotations', description: 'Pin element comments, mark regions or draw pen notes directly on the HTML preview, then copy the scoped brief to your Agent. Your Agent reads open annotations, writes targeted HTML edits and marks each comment resolved.', tools: ['openmotion_design_comments'], prompt: 'List open annotations on my Design Studio project with openmotion_design_comments action=list, apply only the requested changes, and mark each addressed annotation resolved with openmotion_design_comments action=update.' },
  { id: 'scenario-workflows', icon: 'route-line', title: 'Run a workflow end to end', description: 'Open a Topic, Campaign or Role from Workflows to build step by step with shared Assets, or switch to Agent mode to copy concise metadata and grouped Skills for your Agent via MCP.', tools: ['openmotion_assets_use', 'openmotion_design_edit', 'openmotion_design_project'], prompt: 'List available Workflows with openmotion_assets_use (action=scenario, command=catalog) and open or create a run with command=list / command=get / command=create. Load the workflow’s grouped Skills via openmotion_get_skill and workflow guides via openmotion://workflow/* before authoring. Generate media directly with command=generate + command=sync, refine HTML pages with openmotion_design_project and openmotion_design_edit (action=write and action=import_asset) then link with command=link_design, save Agent-created workspace assets directly into the active run’s Assets and step history with command=add_pool (recordIteration=true), and export selected or all deliverables with command=export.' },
] as const;

